import { isPlainObject } from "../domain/profile";

/** Structural equality for setting values (arrays by position, objects by key set). */
export function valuesEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!valuesEqual(a[i], b[i])) return false;
    return true;
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    for (const k of ka) {
      if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
      if (!valuesEqual(a[k], b[k])) return false;
    }
    return true;
  }
  return false;
}
import { SettingValue } from "../domain/profile";
import { valuesEqual } from "./deepEqual";

/** Top-level keys whose values differ (added, removed or changed), sorted. */
export function changedKeys(
  before: Record<string, SettingValue>,
  after: Record<string, SettingValue>,
  ignore: readonly string[] = [],
): string[] {
  const keys = new Set([...Object.keys(before), ...Object.keys(after)]);
  const out: string[] = [];
  for (const k of keys) {
    if (ignore.includes(k)) continue;
    const inBefore = Object.prototype.hasOwnProperty.call(before, k);
    const inAfter = Object.prototype.hasOwnProperty.call(after, k);
    if (inBefore !== inAfter || !valuesEqual(before[k], after[k])) out.push(k);
  }
  return out.sort();
}
import { roundTo } from "../codec/numberFormat";
import { DeviceProfile, SettingValue, isPlainObject } from "../domain/profile";

function normalizeValue(v: SettingValue, decimals: number): SettingValue {
  if (typeof v === "number") return roundTo(v, decimals);
  if (typeof v === "string") return v.trim();
  if (Array.isArray(v)) return v.map((x) => normalizeValue(x, decimals));
  if (isPlainObject(v)) {
    const out: { [k: string]: SettingValue } = {};
    for (const k of Object.keys(v).sort()) out[k] = normalizeValue(v[k] as SettingValue, decimals);
    return out;
  }
  return v;
}

/** Canonical form used for storage and comparison: trimmed strings, rounded numbers, sorted keys. */
export function normalizeProfile(p: DeviceProfile, decimals: number): DeviceProfile {
  return {
    deviceId: p.deviceId.trim(),
    name: p.name.trim(),
    firmware: p.firmware.trim(),
    settings: normalizeValue(p.settings, decimals) as Record<string, SettingValue>,
  };
}

